"""Exercise SD erasure in QEMU and verify the bytes on a disposable guest disk.

Run on Linux with KVM, the maintenance dependencies, and an extracted Debian
kernel directory. No Tesla firmware or physical block device is used.
"""
import argparse
import json
from pathlib import Path
import shutil
import stat
import subprocess
import sys
import tempfile
import time

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from infotainment_lab.qemu_provision import newc, preparation_archive


def regular_files(archive):
    """Read regular files from the newc archive generated by our own builder."""
    files, offset = {}, 0
    while archive[offset:offset + 6] == b'070701':
        header = archive[offset + 6:offset + 110]
        mode = int(header[8:16], 16)
        size = int(header[48:56], 16)
        name_size = int(header[88:96], 16)
        name = archive[offset + 110:offset + 110 + name_size - 1].decode()
        begin = (offset + 110 + name_size + 3) & ~3
        if name == 'TRAILER!!!':
            return files
        if stat.S_ISREG(mode):
            files[name] = archive[begin:begin + size]
        offset = (begin + size + 3) & ~3
    raise ValueError('The maintenance archive is incomplete.')


def benchmark(qemu, kernel_root, length):
    if length <= 0 or length % 512 or length >= 1024**3:
        raise ValueError('Length must be a positive multiple of 512 bytes, below 1 GiB.')
    executable = shutil.which(qemu)
    if not executable:
        raise ValueError('The selected QEMU executable was not found.')
    kernels = list((kernel_root / 'boot').glob('vmlinuz-*'))
    if len(kernels) != 1:
        raise ValueError('The kernel directory must contain exactly one boot/vmlinuz image.')
    kernel = kernels[0].resolve()
    version = kernel.name.removeprefix('vmlinuz-')
    files = regular_files(preparation_archive(1024, kernel_root.resolve(), version))
    modules = '\n'.join(line for line in files['init'].decode().splitlines()
                        if line.startswith('busybox insmod'))
    offset = 1024 * 1024
    files['init'] = f'''#!/usr/bin/busybox sh
set -eu
export PATH=/usr/bin:/usr/sbin
busybox mkdir -p /dev /proc /sys
busybox mount -t devtmpfs devtmpfs /dev
busybox mount -t proc proc /proc
busybox mount -t sysfs sysfs /sys
{modules}
n=0
while [ ! -b /dev/mmcblk0 ]; do
 n=$((n+1)); [ "$n" -lt 20 ] || exit 1; busybox sleep 1
done
echo LAB_ERASE_BEGIN
busybox cat /proc/uptime
busybox blkdiscard -o {offset} -l {length} /dev/mmcblk0
busybox cat /proc/uptime
busybox sync
echo LAB_ERASE_COMPLETE
busybox poweroff -f
'''.encode()
    with tempfile.TemporaryDirectory(prefix='infotainment-sd-bench-') as temporary:
        directory = Path(temporary)
        disk, initrd = directory / 'scratch.raw', directory / 'initrd.cpio'
        with disk.open('xb') as stream:
            stream.truncate(4 * 1024**3)
            stream.seek(offset - 512)
            # Include one neighboring sector on either side of the erased range.
            for _ in range((length + 1024) // 512):
                stream.write(b'\xa5' * 512)
        initrd.write_bytes(newc(files))
        command = [executable, '-machine', 'q35,accel=kvm', '-m', '512',
                   '-nodefaults', '-display', 'none', '-monitor', 'none', '-serial', 'stdio',
                   '-no-reboot', '-nic', 'none', '-kernel', str(kernel), '-initrd', str(initrd),
                   '-append', 'console=ttyS0,115200 rdinit=/init panic=-1 loglevel=3',
                   '-device', 'sdhci-pci', '-drive',
                   'if=none,id=sd,file=' + str(disk).replace(',', ',,') + ',format=raw',
                   '-device', 'sd-card,drive=sd']
        began = time.monotonic()
        result = subprocess.run(command, capture_output=True, text=True, timeout=90)
        elapsed = time.monotonic() - began
        if result.returncode or 'LAB_ERASE_COMPLETE' not in result.stdout:
            raise RuntimeError('Guest erasure did not complete:\n' + result.stdout[-3000:] + result.stderr)
        with disk.open('rb') as stream:
            stream.seek(offset - 512)
            if stream.read(512) != b'\xa5' * 512:
                raise RuntimeError('The preceding sector changed.')
            remaining = length
            while remaining:
                chunk = min(remaining, 1024 * 1024)
                if stream.read(chunk) != b'\xff' * chunk:
                    raise RuntimeError('Erased contents differ from SD semantics.')
                remaining -= chunk
            if stream.read(512) != b'\xa5' * 512:
                raise RuntimeError('The following sector changed.')
        guest_log = result.stdout[result.stdout.index('LAB_ERASE_BEGIN'):]
        stamps = [float(line.split()[0]) for line in guest_log.splitlines()
                  if line and line[0].isdigit() and len(line.split()) == 2]
        return {'qemu': executable, 'kernel_version': version, 'length_bytes': length,
                'host_elapsed_seconds': elapsed,
                'guest_erase_seconds': stamps[1] - stamps[0] if len(stamps) == 2 else None,
                'erased_bytes': '0xff', 'neighboring_sectors': 'unchanged'}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--qemu', default='qemu-system-x86_64')
    parser.add_argument('--kernel-root', type=Path, required=True)
    parser.add_argument('--length', type=int, default=64 * 1024 * 1024 + 512)
    args = parser.parse_args()
    print(json.dumps(benchmark(args.qemu, args.kernel_root, args.length), indent=2))


if __name__ == '__main__':
    main()
